-- Expands the curated recipe catalog from the initial 6 test recipes (0009_recipes.sql) to the
-- full 90-recipe launch catalog. Written as a NEW migration rather than editing 0009 directly,
-- since 0009 may already have been run against a live project.
--
-- Three of the original 6 test recipes don't correspond to anything in the approved 90-recipe
-- launch list and are retired here to avoid conceptual duplicates:
--   - oatmeal-porridge   (superseded by the more specific banana-oatmeal / apple-cinnamon-oatmeal)
--   - taco               (superseded by the more specific beef-tacos / chicken-tacos)
--   - chicken-wok-noodles (superseded by the equivalent, catalog-titled chicken-noodle-stir-fry)
-- The other 3 (scrambled-eggs-bacon, ham-cheese-sandwich, fish-cakes-mashed-potatoes) reappear
-- unchanged below as part of the 90 and are updated in place via the upsert, not duplicated.
delete from public.recipes where slug in ('oatmeal-porridge', 'taco', 'chicken-wok-noodles');

on conflict (slug) do update set
  title_en = excluded.title_en,
  title_nb = excluded.title_nb,
  meal_type = excluded.meal_type,
  category = excluded.category,
  is_vegetarian = excluded.is_vegetarian,
  ingredients = excluded.ingredients,
  instructions_en = excluded.instructions_en,
  instructions_nb = excluded.instructions_nb,
  source_url = excluded.source_url;
