insert into public.recipes (slug, title_en, title_nb, meal_type, category, is_vegetarian, ingredients, instructions_en, instructions_nb, source_url)
values
  ('banana-oatmeal', 'Banana Oatmeal', 'Havregrøt med banan', array['breakfast'], 'Norwegian', false, '[{"canonical_name": "oats", "name_en": "Oats", "name_nb": "Havregryn", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "6 dl", "measure_nb": "6 dl"}, {"canonical_name": "salt", "name_en": "Salt", "name_nb": "Salt", "measure_en": "1 tsp", "measure_nb": "1 ts"}, {"canonical_name": "banana", "name_en": "Banana", "name_nb": "Banan", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "honey", "name_en": "Honey", "name_nb": "Honning", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Bring the milk to a boil, stir in the oats and salt, and simmer 5-8 minutes, stirring occasionally. Top with sliced banana and a drizzle of honey.', 'Kok opp melken, rør inn havregryn og salt, og la det småkoke i 5-8 minutter mens du rører innimellom. Topp med skivet banan og litt honning.', null),
  ('apple-cinnamon-oatmeal', 'Apple and Cinnamon Oatmeal', 'Havregrøt med eple og kanel', array['breakfast'], 'Norwegian', false, '[{"canonical_name": "oats", "name_en": "Oats", "name_nb": "Havregryn", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "6 dl", "measure_nb": "6 dl"}, {"canonical_name": "apple", "name_en": "Apple", "name_nb": "Eple", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "cinnamon", "name_en": "Cinnamon", "name_nb": "Kanel", "measure_en": "1 tsp", "measure_nb": "1 ts"}, {"canonical_name": "sugar", "name_en": "Sugar", "name_nb": "Sukker", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Bring the milk to a boil and stir in the oats. Simmer 5-8 minutes. Dice the apple and stir in with the cinnamon; sweeten to taste.', 'Kok opp melken og rør inn havregrynene. La det småkoke i 5-8 minutter. Kutt eplet i biter og rør inn sammen med kanel; søt etter smak.', null),
  ('overnight-oats-berries', 'Overnight Oats with Berries', 'Overnight oats med bær', array['breakfast'], 'Nordic', true, '[{"canonical_name": "oats", "name_en": "Oats", "name_nb": "Havregryn", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "yogurt", "name_en": "Yogurt", "name_nb": "Yoghurt", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "1 dl", "measure_nb": "1 dl"}, {"canonical_name": "berries", "name_en": "Berries", "name_nb": "Bær", "measure_en": "1 dl", "measure_nb": "1 dl"}, {"canonical_name": "honey", "name_en": "Honey", "name_nb": "Honning", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Mix the oats, yogurt, milk, and honey in a jar and refrigerate overnight. Top with berries before serving.', 'Bland havregryn, yoghurt, melk og honning i et glass og sett kaldt over natten. Topp med bær før servering.', null),
  ('yogurt-muesli-berries', 'Yogurt with Muesli and Berries', 'Yoghurt med müsli og bær', array['breakfast'], 'Nordic', true, '[{"canonical_name": "yogurt", "name_en": "Yogurt", "name_nb": "Yoghurt", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "muesli", "name_en": "Muesli", "name_nb": "Müsli", "measure_en": "1 dl", "measure_nb": "1 dl"}, {"canonical_name": "berries", "name_en": "Berries", "name_nb": "Bær", "measure_en": "1 dl", "measure_nb": "1 dl"}, {"canonical_name": "honey", "name_en": "Honey", "name_nb": "Honning", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Spoon the yogurt into a bowl and top with muesli, berries, and a drizzle of honey.', 'Ha yoghurten i en bolle og topp med müsli, bær og litt honning.', null),
  ('yogurt-banana-nuts', 'Yogurt with Banana and Nuts', 'Yoghurt med banan og nøtter', array['breakfast'], 'Nordic', true, '[{"canonical_name": "yogurt", "name_en": "Yogurt", "name_nb": "Yoghurt", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "banana", "name_en": "Banana", "name_nb": "Banan", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "nuts", "name_en": "Nuts", "name_nb": "Nøtter", "measure_en": "1/2 dl", "measure_nb": "1/2 dl"}, {"canonical_name": "honey", "name_en": "Honey", "name_nb": "Honning", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Slice the banana into the yogurt and top with nuts and a drizzle of honey.', 'Skjær banan i yoghurten og topp med nøtter og litt honning.', null),
  ('scrambled-eggs-bread', 'Scrambled Eggs with Bread', 'Eggerøre med brød', array['breakfast'], 'Breakfast', true, '[{"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "2 tbsp", "measure_nb": "2 ss"}, {"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "chives", "name_en": "Chives", "name_nb": "Gressløk", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Whisk the eggs with the milk. Melt the butter in a pan and scramble the eggs over low heat. Serve with bread and chives on top.', 'Visp eggene sammen med melken. Smelt smøret i en panne og rør eggene til eggerøre på lav varme. Server med brød og gressløk på toppen.', null),
  ('scrambled-eggs-bacon', 'Scrambled Eggs with Bacon', 'Eggerøre med bacon', array['breakfast'], 'Breakfast', false, '[{"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "bacon", "name_en": "Bacon", "name_nb": "Bacon", "measure_en": "100 g", "measure_nb": "100 g"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}, {"canonical_name": "chives", "name_en": "Chives", "name_nb": "Gressløk", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Fry the bacon until crisp and set aside. Whisk the eggs, melt the butter in the same pan, and scramble the eggs over low heat. Serve topped with the bacon and chives.', 'Stek baconet sprøtt og sett til side. Visp sammen eggene, smelt smøret i samme panne, og rør eggene til eggerøre på lav varme. Server med baconet og gressløk på toppen.', null),
  ('boiled-egg-bread', 'Boiled Egg with Bread', 'Kokt egg med brød', array['breakfast'], 'Breakfast', true, '[{"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "to taste", "measure_nb": "etter smak"}, {"canonical_name": "salt", "name_en": "Salt", "name_nb": "Salt", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Boil the eggs for 6-8 minutes depending on how set you like the yolk. Serve with buttered bread and a pinch of salt.', 'Kok eggene i 6-8 minutter avhengig av hvor godt du vil ha plommen. Server med smurt brød og litt salt.', null),
  ('fried-egg-bread', 'Fried Egg on Bread', 'Speilegg på brød', array['breakfast'], 'Breakfast', true, '[{"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}, {"canonical_name": "salt", "name_en": "Salt", "name_nb": "Salt", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Fry the eggs in butter over medium heat until the whites are set. Serve on buttered bread with a pinch of salt.', 'Stek eggene i smør på middels varme til hviten har stivnet. Server på smurt brød med litt salt.', null),
  ('ham-cheese-omelette', 'Ham and Cheese Omelette', 'Omelett med skinke og ost', array['breakfast','lunch'], 'Breakfast', false, '[{"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "50 g", "measure_nb": "50 g"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Whisk the eggs and pour into a hot, buttered pan. Scatter ham and cheese over half, fold, and cook until the egg is set.', 'Visp eggene og hell dem i en varm, smurt panne. Fordel skinke og ost over den ene halvdelen, brett omeletten og stek til egget har stivnet.', null),
  ('vegetable-omelette', 'Vegetable Omelette', 'Grønnsaksomelett', array['breakfast','lunch'], 'Breakfast', true, '[{"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1/2", "measure_nb": "1/2"}, {"canonical_name": "mushroom", "name_en": "Mushroom", "name_nb": "Sopp", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "spinach", "name_en": "Spinach", "name_nb": "Spinat", "measure_en": "1 handful", "measure_nb": "1 neve"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Sauté the diced pepper and mushroom in butter until soft, then add the spinach until wilted. Pour in the whisked eggs and cook until set.', 'Fres paprika og sopp i terninger i smør til de er møre, tilsett spinaten til den faller sammen. Hell i de vispede eggene og stek til de har stivnet.', null),
  ('ham-cheese-sandwich', 'Ham and Cheese Sandwich', 'Brødskive med skinke og ost', array['breakfast','lunch'], 'Norwegian', false, '[{"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Butter the bread, then top with ham and cheese.', 'Smør brødskivene, og legg på skinke og ost.', null),
  ('egg-avocado-sandwich', 'Egg and Avocado Sandwich', 'Brødskive med egg og avokado', array['breakfast','lunch'], 'Breakfast', true, '[{"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "avocado", "name_en": "Avocado", "name_nb": "Avokado", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "salt", "name_en": "Salt", "name_nb": "Salt", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Boil and slice the eggs. Mash the avocado and spread on the bread, then top with the egg slices and a pinch of salt.', 'Kok og skjær eggene i skiver. Mos avokadoen og smør den på brødet, legg på eggeskivene og litt salt.', null),
  ('whole-grain-pancakes', 'Whole-Grain Pancakes', 'Grove pannekaker', array['breakfast','dinner'], 'Nordic', true, '[{"canonical_name": "flour", "name_en": "Flour", "name_nb": "Mel", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "5 dl", "measure_nb": "5 dl"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}, {"canonical_name": "salt", "name_en": "Salt", "name_nb": "Salt", "measure_en": "1 pinch", "measure_nb": "1 klype"}]'::jsonb, 'Whisk the flour, milk, eggs, and salt into a smooth batter. Fry thin pancakes in butter until golden on both sides.', 'Visp mel, melk, egg og salt til en jevn røre. Stek tynne pannekaker i smør til de er gyldne på begge sider.', null),
  ('banana-pancakes', 'Banana Pancakes', 'Bananpannekaker', array['breakfast','dinner'], 'Nordic', true, '[{"canonical_name": "flour", "name_en": "Flour", "name_nb": "Mel", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "5 dl", "measure_nb": "5 dl"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "banana", "name_en": "Banana", "name_nb": "Banan", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Mash one banana into the batter of flour, milk, and eggs. Fry pancakes in butter and serve topped with slices of the second banana.', 'Mos en banan inn i røren av mel, melk og egg. Stek pannekaker i smør og server toppet med skiver av den andre bananen.', null),
  ('banana-berry-smoothie', 'Banana and Berry Smoothie', 'Banan- og bærsmoothie', array['breakfast'], 'Nordic', true, '[{"canonical_name": "banana", "name_en": "Banana", "name_nb": "Banan", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "berries", "name_en": "Berries", "name_nb": "Bær", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "yogurt", "name_en": "Yogurt", "name_nb": "Yoghurt", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "1 dl", "measure_nb": "1 dl"}]'::jsonb, 'Blend the banana, berries, yogurt, and milk until smooth.', 'Kjør banan, bær, yoghurt og melk i en blender til smoothien er jevn.', null),
  ('banana-oat-smoothie', 'Banana and Oat Smoothie', 'Banan- og havresmoothie', array['breakfast'], 'Nordic', true, '[{"canonical_name": "banana", "name_en": "Banana", "name_nb": "Banan", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "oats", "name_en": "Oats", "name_nb": "Havregryn", "measure_en": "1/2 dl", "measure_nb": "1/2 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "honey", "name_en": "Honey", "name_nb": "Honning", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Blend the banana, oats, milk, and honey until smooth.', 'Kjør banan, havregryn, melk og honning i en blender til smoothien er jevn.', null),
  ('chicken-wrap', 'Chicken Wrap', 'Kyllingwrap', array['lunch'], 'Wraps', false, '[{"canonical_name": "tortilla wrap", "name_en": "Tortilla wrap", "name_nb": "Tortillalefse", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/4 head", "measure_nb": "1/4 hode"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "mayonnaise", "name_en": "Mayonnaise", "name_nb": "Majones", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Fry and slice the chicken breast. Fill the wraps with lettuce, tomato, chicken, and a spoonful of mayonnaise, then roll up tightly.', 'Stek og skjær kyllingfileten i strimler. Fyll wrapsene med salat, tomat, kylling og en klatt majones, og rull godt sammen.', null),
  ('salmon-wrap', 'Salmon Wrap', 'Lakswrap', array['lunch'], 'Wraps', false, '[{"canonical_name": "tortilla wrap", "name_en": "Tortilla wrap", "name_nb": "Tortillalefse", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "salmon", "name_en": "Salmon", "name_nb": "Laks", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "cucumber", "name_en": "Cucumber", "name_nb": "Agurk", "measure_en": "1/2", "measure_nb": "1/2"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/4 head", "measure_nb": "1/4 hode"}, {"canonical_name": "cream cheese", "name_en": "Cream cheese", "name_nb": "Kremost", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Pan-fry or use leftover cooked salmon, flaked. Spread cream cheese on the wraps and fill with lettuce, cucumber, and salmon, then roll up.', 'Stek laksen, eller bruk restelaks, og del den opp. Smør kremost på wrapsene og fyll med salat, agurk og laks, og rull sammen.', null),
  ('ham-cheese-wrap', 'Ham and Cheese Wrap', 'Wrap med skinke og ost', array['lunch'], 'Wraps', false, '[{"canonical_name": "tortilla wrap", "name_en": "Tortilla wrap", "name_nb": "Tortillalefse", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "4 slices", "measure_nb": "4 skiver"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "4 slices", "measure_nb": "4 skiver"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/4 head", "measure_nb": "1/4 hode"}, {"canonical_name": "mustard", "name_en": "Mustard", "name_nb": "Sennep", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Spread a little mustard on the wraps, layer with ham, cheese, and lettuce, then roll up tightly.', 'Smør litt sennep på wrapsene, legg på skinke, ost og salat, og rull godt sammen.', null),
  ('chicken-salad', 'Chicken Salad', 'Kyllingsalat', array['lunch'], 'Salads', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/2 head", "measure_nb": "1/2 hode"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "cucumber", "name_en": "Cucumber", "name_nb": "Agurk", "measure_en": "1/2", "measure_nb": "1/2"}, {"canonical_name": "olive oil", "name_en": "Olive oil", "name_nb": "Olivenolje", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Fry and slice the chicken breast. Toss with lettuce, tomato, and cucumber, and drizzle with olive oil.', 'Stek og skjær kyllingfileten i skiver. Vend sammen med salat, tomat og agurk, og ha over olivenolje.', null),
  ('chicken-pasta-salad', 'Chicken Pasta Salad', 'Pastasalat med kylling', array['lunch'], 'Salads', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "250 g", "measure_nb": "250 g"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "mayonnaise", "name_en": "Mayonnaise", "name_nb": "Majones", "measure_en": "3 tbsp", "measure_nb": "3 ss"}]'::jsonb, 'Cook the pasta and let it cool. Fry and dice the chicken. Toss the pasta with chicken, tomato, pepper, and mayonnaise.', 'Kok pastaen og la den avkjøles. Stek og terning kyllingen. Vend sammen pasta, kylling, tomat, paprika og majones.', null),
  ('ham-pasta-salad', 'Ham Pasta Salad', 'Pastasalat med skinke', array['lunch'], 'Salads', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "250 g", "measure_nb": "250 g"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "corn", "name_en": "Corn", "name_nb": "Mais", "measure_en": "1 dl", "measure_nb": "1 dl"}, {"canonical_name": "mayonnaise", "name_en": "Mayonnaise", "name_nb": "Majones", "measure_en": "3 tbsp", "measure_nb": "3 ss"}]'::jsonb, 'Cook the pasta and let it cool. Dice the ham and pepper, and toss everything with the corn and mayonnaise.', 'Kok pastaen og la den avkjøles. Terning skinke og paprika, og vend sammen med mais og majones.', null),
  ('egg-salad-sandwich', 'Egg Salad Sandwich', 'Brødskive med eggesalat', array['lunch'], 'Sandwiches', true, '[{"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "mayonnaise", "name_en": "Mayonnaise", "name_nb": "Majones", "measure_en": "2 tbsp", "measure_nb": "2 ss"}, {"canonical_name": "chives", "name_en": "Chives", "name_nb": "Gressløk", "measure_en": "to taste", "measure_nb": "etter smak"}, {"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "4 slices", "measure_nb": "4 skiver"}]'::jsonb, 'Boil and chop the eggs. Mix with mayonnaise and chives, and spread generously on the bread.', 'Kok og hakk eggene. Bland med majones og gressløk, og smør rikelig på brødet.', null),
  ('ham-cheese-toast', 'Ham and Cheese Toast', 'Skinke- og osttoast', array['lunch','dinner'], 'Sandwiches', false, '[{"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "4 slices", "measure_nb": "4 skiver"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "2 slices", "measure_nb": "2 skiver"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "4 slices", "measure_nb": "4 skiver"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Layer ham and cheese between the bread slices and butter the outsides. Toast in a pan until golden and the cheese has melted.', 'Legg skinke og ost mellom brødskivene og smør utsiden. Stek i panne til brødet er gyllent og osten har smeltet.', null),
  ('grilled-cheese-sandwich', 'Grilled Cheese Sandwich', 'Ostetoast', array['lunch','dinner'], 'Sandwiches', true, '[{"canonical_name": "bread", "name_en": "Bread", "name_nb": "Brød", "measure_en": "4 slices", "measure_nb": "4 skiver"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "6 slices", "measure_nb": "6 skiver"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Layer cheese between the bread slices and butter the outsides. Toast in a pan over medium heat until golden and the cheese has melted.', 'Legg ost mellom brødskivene og smør utsiden. Stek i panne på middels varme til brødet er gyllent og osten har smeltet.', null),
  ('ham-cheese-quesadilla', 'Ham and Cheese Quesadilla', 'Quesadilla med skinke og ost', array['lunch','dinner'], 'Mexican', false, '[{"canonical_name": "tortilla wrap", "name_en": "Tortilla wrap", "name_nb": "Tortillalefse", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "3 slices", "measure_nb": "3 skiver"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "100 g", "measure_nb": "100 g"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Scatter ham and cheese over one tortilla and top with the second. Fry in butter until golden on both sides and the cheese has melted.', 'Fordel skinke og ost på en tortilla og legg på den andre. Stek i smør til begge sider er gyldne og osten har smeltet.', null),
  ('chicken-quesadilla', 'Chicken Quesadilla', 'Quesadilla med kylling', array['lunch','dinner'], 'Mexican', false, '[{"canonical_name": "tortilla wrap", "name_en": "Tortilla wrap", "name_nb": "Tortillalefse", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "250 g", "measure_nb": "250 g"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "100 g", "measure_nb": "100 g"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1/2", "measure_nb": "1/2"}, {"canonical_name": "taco seasoning", "name_en": "Taco seasoning", "name_nb": "Tacokrydder", "measure_en": "1 tsp", "measure_nb": "1 ts"}]'::jsonb, 'Fry the diced chicken with the taco seasoning. Scatter chicken, pepper, and cheese over one tortilla, top with the second, and fry until golden and melted.', 'Stek terningskåret kylling med tacokrydder. Fordel kylling, paprika og ost på en tortilla, legg på den andre, og stek til den er gyllen og osten har smeltet.', null),
  ('potato-onion-omelette', 'Potato and Onion Omelette', 'Potet- og løkomelett', array['breakfast','lunch'], 'Nordic', true, '[{"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "5", "measure_nb": "5"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}, {"canonical_name": "salt", "name_en": "Salt", "name_nb": "Salt", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Fry sliced potato and onion in butter until tender. Pour the whisked eggs over and cook on low heat until set.', 'Stek skivet potet og løk i smør til de er møre. Hell over de vispede eggene og stek på lav varme til de har stivnet.', null),
  ('tomato-soup', 'Tomato Soup', 'Tomatsuppe', array['lunch','dinner'], 'Soups', true, '[{"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "2 cans", "measure_nb": "2 bokser"}, {"canonical_name": "vegetable stock", "name_en": "Vegetable stock", "name_nb": "Grønnsakskraft", "measure_en": "5 dl", "measure_nb": "5 dl"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "1 clove", "measure_nb": "1 fedd"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "1 dl", "measure_nb": "1 dl"}]'::jsonb, 'Sauté the onion and garlic, add the canned tomatoes and stock, and simmer for 15 minutes. Blend smooth and stir in the cream.', 'Fres løk og hvitløk, tilsett hermetiske tomater og kraft, og la det småkoke i 15 minutter. Kjør glatt med stavmikser og rør inn fløten.', null),
  ('creamy-vegetable-soup', 'Creamy Vegetable Soup', 'Kremet grønnsakssuppe', array['lunch','dinner'], 'Soups', true, '[{"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "leek", "name_en": "Leek", "name_nb": "Purre", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "vegetable stock", "name_en": "Vegetable stock", "name_nb": "Grønnsakskraft", "measure_en": "6 dl", "measure_nb": "6 dl"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "1 dl", "measure_nb": "1 dl"}]'::jsonb, 'Simmer the diced carrot, potato, and leek in the stock until tender, about 15 minutes. Blend smooth and stir in the cream.', 'La gulrot, potet og purre i terninger småkoke i kraften til de er møre, ca. 15 minutter. Kjør glatt og rør inn fløten.', null),
  ('chicken-soup', 'Chicken Soup', 'Kyllingsuppe', array['lunch','dinner'], 'Soups', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "chicken stock", "name_en": "Chicken stock", "name_nb": "Kyllingkraft", "measure_en": "8 dl", "measure_nb": "8 dl"}, {"canonical_name": "noodles", "name_en": "Noodles", "name_nb": "Nudler", "measure_en": "100 g", "measure_nb": "100 g"}]'::jsonb, 'Simmer the chicken breast in the stock until cooked through, then shred it. Add the diced carrot and potato and simmer until tender, then add the noodles for the last few minutes.', 'La kyllingfileten trekke i kraften til den er gjennomstekt, og del den opp. Ha i gulrot og potet i terninger og la det småkoke til de er møre, tilsett nudlene de siste minuttene.', null),
  ('baked-potato-ham-cheese', 'Baked Potato with Ham and Cheese', 'Bakt potet med skinke og ost', array['lunch','dinner'], 'Norwegian', false, '[{"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "100 g", "measure_nb": "100 g"}, {"canonical_name": "sour cream", "name_en": "Sour cream", "name_nb": "Rømme", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "chives", "name_en": "Chives", "name_nb": "Gressløk", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Bake the potatoes at 200°C (400°F) for about 45 minutes until soft. Cut open and top with ham, cheese, sour cream, and chives.', 'Bak potetene på 200°C i ca. 45 minutter til de er møre. Del dem opp og topp med skinke, ost, rømme og gressløk.', null),
  ('chicken-couscous-salad', 'Chicken Couscous Salad', 'Couscoussalat med kylling', array['lunch'], 'Salads', false, '[{"canonical_name": "couscous", "name_en": "Couscous", "name_nb": "Couscous", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "cucumber", "name_en": "Cucumber", "name_nb": "Agurk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "olive oil", "name_en": "Olive oil", "name_nb": "Olivenolje", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Prepare the couscous according to the package. Fry and dice the chicken, and toss everything with the diced cucumber, tomato, and olive oil.', 'Tilbered couscousen etter anvisning på pakken. Stek og terning kyllingen, og vend sammen med agurk, tomat i terninger og olivenolje.', null),
  ('spaghetti-bolognese', 'Spaghetti Bolognese', 'Spaghetti bolognese', array['dinner'], 'Pasta', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "2 cans", "measure_nb": "2 bokser"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "2 cloves", "measure_nb": "2 fedd"}]'::jsonb, 'Brown the ground beef with the onion and garlic. Add the canned tomatoes and simmer for 20 minutes. Serve over cooked spaghetti.', 'Brun kjøttdeigen sammen med løk og hvitløk. Tilsett hermetiske tomater og la det småkoke i 20 minutter. Server over kokt spaghetti.', null),
  ('creamy-chicken-pasta', 'Creamy Chicken Pasta', 'Kremet kyllingpasta', array['dinner'], 'Pasta', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "2 cloves", "measure_nb": "2 fedd"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "50 g", "measure_nb": "50 g"}]'::jsonb, 'Fry the sliced chicken with the garlic until cooked through. Add the cream and simmer a few minutes, then stir in the cheese. Toss with cooked pasta.', 'Stek kyllingstrimlene sammen med hvitløk til de er gjennomstekte. Tilsett fløte og la det småkoke noen minutter, rør inn osten. Vend sammen med kokt pasta.', null),
  ('pasta-carbonara', 'Pasta Carbonara', 'Pasta carbonara', array['dinner'], 'Pasta', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "bacon", "name_en": "Bacon", "name_nb": "Bacon", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "50 g", "measure_nb": "50 g"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "1 clove", "measure_nb": "1 fedd"}]'::jsonb, 'Cook the pasta. Fry the bacon with the garlic. Whisk the eggs with the cheese, then toss through the hot, drained pasta together with the bacon off the heat, so the eggs turn creamy without scrambling.', 'Kok pastaen. Stek baconet sammen med hvitløk. Visp eggene med osten, og vend dette inn i den varme, avrente pastaen sammen med baconet uten varme, slik at eggene blir kremete uten å bli til eggerøre.', null),
  ('chicken-pesto-pasta', 'Chicken Pesto Pasta', 'Pestopasta med kylling', array['dinner'], 'Pasta', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "350 g", "measure_nb": "350 g"}, {"canonical_name": "pesto", "name_en": "Pesto", "name_nb": "Pesto", "measure_en": "3 tbsp", "measure_nb": "3 ss"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "30 g", "measure_nb": "30 g"}]'::jsonb, 'Fry the sliced chicken until cooked through. Toss the cooked pasta with the chicken, pesto, and diced tomato. Top with grated cheese.', 'Stek kyllingstrimlene til de er gjennomstekte. Vend den kokte pastaen sammen med kylling, pesto og tomat i terninger. Topp med revet ost.', null),
  ('pasta-tomato-sauce', 'Pasta with Tomato Sauce', 'Pasta med tomatsaus', array['dinner'], 'Pasta', true, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "2 cans", "measure_nb": "2 bokser"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "2 cloves", "measure_nb": "2 fedd"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "olive oil", "name_en": "Olive oil", "name_nb": "Olivenolje", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Sauté the onion and garlic in olive oil, add the canned tomatoes, and simmer for 15-20 minutes. Season and toss with the cooked pasta.', 'Fres løk og hvitløk i olivenolje, tilsett hermetiske tomater, og la det småkoke i 15-20 minutter. Smak til og vend sammen med kokt pasta.', null),
  ('lasagne', 'Lasagne', 'Lasagne', array['dinner'], 'Pasta', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "2 cans", "measure_nb": "2 bokser"}, {"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "12 sheets", "measure_nb": "12 plater"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "150 g", "measure_nb": "150 g"}]'::jsonb, 'Brown the ground beef and simmer with the canned tomatoes for 15 minutes. Layer with lasagne sheets and cream in a dish, top with cheese, and bake at 200°C (400°F) for 30-35 minutes.', 'Brun kjøttdeigen og la den småkoke med hermetiske tomater i 15 minutter. Lag lag med lasagneplater og fløte i en form, topp med ost, og stek på 200°C i 30-35 minutter.', null),
