  ('beef-quesadilla', 'Beef Quesadilla', 'Quesadilla med kjøttdeig', array['lunch','dinner'], 'Mexican', false, '[{"canonical_name": "tortilla wrap", "name_en": "Tortilla wrap", "name_nb": "Tortillalefse", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "100 g", "measure_nb": "100 g"}, {"canonical_name": "taco seasoning", "name_en": "Taco seasoning", "name_nb": "Tacokrydder", "measure_en": "1 tsp", "measure_nb": "1 ts"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1/2", "measure_nb": "1/2"}]'::jsonb, 'Brown the ground beef with the taco seasoning. Scatter beef, pepper, and cheese over one tortilla, top with the second, and fry until golden and the cheese has melted.', 'Brun kjøttdeigen med tacokrydder. Fordel kjøttdeig, paprika og ost på en tortilla, legg på den andre, og stek til den er gyllen og osten har smeltet.', null),
  ('beef-rice-burrito', 'Beef and Rice Burrito', 'Burrito med kjøttdeig og ris', array['lunch','dinner'], 'Mexican', false, '[{"canonical_name": "tortilla wrap", "name_en": "Tortilla wrap", "name_nb": "Tortillalefse", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "kidney beans", "name_en": "Kidney beans", "name_nb": "Kidneybønner", "measure_en": "1 can", "measure_nb": "1 boks"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "80 g", "measure_nb": "80 g"}, {"canonical_name": "taco seasoning", "name_en": "Taco seasoning", "name_nb": "Tacokrydder", "measure_en": "1 tsp", "measure_nb": "1 ts"}]'::jsonb, 'Cook the rice. Brown the ground beef with the taco seasoning and stir in the drained kidney beans. Fill the tortillas with rice, beef mixture, and cheese, then roll up.', 'Kok risen. Brun kjøttdeigen med tacokrydder og rør inn avrente kidneybønner. Fyll tortillaene med ris, kjøttdeigblanding og ost, og rull sammen.', null),
  ('chicken-noodle-stir-fry', 'Chicken Noodle Stir-Fry', 'Kyllingwok med nudler', array['dinner'], 'Asian', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "noodles", "name_en": "Noodles", "name_nb": "Nudler", "measure_en": "250 g", "measure_nb": "250 g"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "broccoli", "name_en": "Broccoli", "name_nb": "Brokkoli", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "soy sauce", "name_en": "Soy sauce", "name_nb": "Soyasaus", "measure_en": "3 tbsp", "measure_nb": "3 ss"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "2 cloves", "measure_nb": "2 fedd"}, {"canonical_name": "ginger", "name_en": "Ginger", "name_nb": "Ingefær", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Cook the noodles per package instructions. Slice the chicken and stir-fry in a hot wok with garlic and ginger until cooked through. Add the pepper and broccoli and stir-fry a few more minutes. Add the noodles and soy sauce, and toss to combine.', 'Kok nudlene etter anvisning på pakken. Skjær kyllingen i strimler og wok den sammen med hvitløk og ingefær til den er gjennomstekt. Ha i paprika og brokkoli, og wok noen minutter til. Ha i nudler og soyasaus, og vend godt sammen.', null),
  ('chicken-rice-stir-fry', 'Chicken and Rice Stir-Fry', 'Kyllingwok med ris', array['dinner'], 'Asian', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "broccoli", "name_en": "Broccoli", "name_nb": "Brokkoli", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "soy sauce", "name_en": "Soy sauce", "name_nb": "Soyasaus", "measure_en": "3 tbsp", "measure_nb": "3 ss"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "2 cloves", "measure_nb": "2 fedd"}]'::jsonb, 'Cook the rice. Slice the chicken and stir-fry with garlic until cooked through. Add the pepper and broccoli and stir-fry a few more minutes, then add the soy sauce. Serve over the rice.', 'Kok risen. Skjær kyllingen i strimler og wok den sammen med hvitløk til den er gjennomstekt. Ha i paprika og brokkoli og wok noen minutter til, tilsett soyasaus. Server over risen.', null),
  ('beef-stir-fry-vegetables', 'Beef Stir-Fry with Vegetables', 'Biffwok med grønnsaker', array['dinner'], 'Asian', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "broccoli", "name_en": "Broccoli", "name_nb": "Brokkoli", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "soy sauce", "name_en": "Soy sauce", "name_nb": "Soyasaus", "measure_en": "3 tbsp", "measure_nb": "3 ss"}, {"canonical_name": "ginger", "name_en": "Ginger", "name_nb": "Ingefær", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Brown the beef in a hot wok. Add the sliced pepper, broccoli, and carrot and stir-fry until tender-crisp. Stir in the soy sauce and ginger.', 'Brun kjøttdeigen i en varm wok. Ha i paprika, brokkoli og gulrot i strimler og wok til grønnsakene er møre, men fortsatt har tyggemotstand. Rør inn soyasaus og ingefær.', null),
  ('chicken-egg-fried-rice', 'Chicken and Egg Fried Rice', 'Stekt ris med kylling og egg', array['dinner'], 'Asian', false, '[{"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "soy sauce", "name_en": "Soy sauce", "name_nb": "Soyasaus", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Cook the rice ahead and let it cool (or use leftover rice). Stir-fry the diced chicken and pepper until cooked. Push to the side, scramble the eggs in the pan, then mix in the rice and soy sauce.', 'Kok risen på forhånd og la den avkjøles (eller bruk restris). Wok kylling og paprika i terninger til kyllingen er gjennomstekt. Skyv til side, rør eggene til eggerøre i pannen, og bland deretter inn ris og soyasaus.', null),
  ('chicken-curry-rice', 'Chicken Curry with Rice', 'Kyllingcurry med ris', array['dinner'], 'Asian', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "curry powder", "name_en": "Curry powder", "name_nb": "Karripulver", "measure_en": "1 tbsp", "measure_nb": "1 ss"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}]'::jsonb, 'Fry the diced chicken, onion, and pepper. Stir in the curry powder, then add the cream and simmer for 10 minutes. Serve over rice.', 'Stek kylling, løk og paprika i terninger. Rør inn karripulver, tilsett fløte, og la det småkoke i 10 minutter. Server over ris.', null),
  ('chili-con-carne', 'Chili Con Carne', 'Chili con carne', array['dinner'], 'Mexican', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "kidney beans", "name_en": "Kidney beans", "name_nb": "Kidneybønner", "measure_en": "1 can", "measure_nb": "1 boks"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "2 cans", "measure_nb": "2 bokser"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "chili flakes", "name_en": "Chili flakes", "name_nb": "Chiliflak", "measure_en": "1 tsp", "measure_nb": "1 ts"}, {"canonical_name": "cumin", "name_en": "Cumin", "name_nb": "Spisskummen", "measure_en": "1 tsp", "measure_nb": "1 ts"}]'::jsonb, 'Brown the ground beef with the onion. Add the canned tomatoes, drained kidney beans, chili flakes, and cumin, and simmer for 20 minutes.', 'Brun kjøttdeigen sammen med løk. Tilsett hermetiske tomater, avrente kidneybønner, chiliflak og spisskummen, og la det småkoke i 20 minutter.', null),
  ('beef-mince-stew-rice', 'Beef Mince Stew with Rice', 'Kjøttdeiggryte med ris', array['dinner'], 'Norwegian', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "beef stock", "name_en": "Beef stock", "name_nb": "Oksekraft", "measure_en": "5 dl", "measure_nb": "5 dl"}, {"canonical_name": "tomato paste", "name_en": "Tomato paste", "name_nb": "Tomatpuré", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Brown the ground beef with the onion, add the diced carrot, stock, and tomato paste, and simmer for 20 minutes. Serve over rice.', 'Brun kjøttdeigen sammen med løk, tilsett gulrot i terninger, kraft og tomatpuré, og la det småkoke i 20 minutter. Server over ris.', null),
  ('sausage-stew', 'Sausage Stew', 'Pølsegryte', array['dinner'], 'Norwegian', false, '[{"canonical_name": "sausages", "name_en": "Sausages", "name_nb": "Pølser", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "1 can", "measure_nb": "1 boks"}, {"canonical_name": "beef stock", "name_en": "Beef stock", "name_nb": "Oksekraft", "measure_en": "3 dl", "measure_nb": "3 dl"}]'::jsonb, 'Slice the sausages and brown them. Add the diced potato, carrot, canned tomatoes, and stock, and simmer for 20 minutes until the vegetables are tender.', 'Skjær pølsene i skiver og brun dem. Tilsett potet og gulrot i terninger, hermetiske tomater og kraft, og la det småkoke i 20 minutter til grønnsakene er møre.', null),
  ('sausages-mashed-potatoes', 'Sausages with Mashed Potatoes', 'Pølser med potetmos', array['dinner'], 'Norwegian', false, '[{"canonical_name": "sausages", "name_en": "Sausages", "name_nb": "Pølser", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "800 g", "measure_nb": "800 g"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "50 g", "measure_nb": "50 g"}]'::jsonb, 'Boil the potatoes until tender and mash with milk and butter. Fry or boil the sausages and serve together.', 'Kok potetene møre og mos dem med melk og smør. Stek eller kok pølsene og server sammen.', null),
  ('fish-cakes-mashed-potatoes', 'Fish Cakes with Mashed Potatoes', 'Fiskekaker med potetmos', array['dinner'], 'Norwegian', false, '[{"canonical_name": "fish cakes", "name_en": "Fish cakes", "name_nb": "Fiskekaker", "measure_en": "8", "measure_nb": "8"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "800 g", "measure_nb": "800 g"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "50 g", "measure_nb": "50 g"}, {"canonical_name": "peas", "name_en": "Peas", "name_nb": "Erter", "measure_en": "200 g", "measure_nb": "200 g"}]'::jsonb, 'Boil the potatoes until tender, then mash with milk and butter. Fry the fish cakes until golden on both sides. Boil the peas briefly. Serve together.', 'Kok potetene møre, og mos dem med melk og smør. Stek fiskekakene gylne på begge sider. Kok ertene kort. Server sammen.', null),
  ('fish-cakes-potatoes-vegetables', 'Fish Cakes with Potatoes and Vegetables', 'Fiskekaker med poteter og grønnsaker', array['dinner'], 'Norwegian', false, '[{"canonical_name": "fish cakes", "name_en": "Fish cakes", "name_nb": "Fiskekaker", "measure_en": "8", "measure_nb": "8"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "broccoli", "name_en": "Broccoli", "name_nb": "Brokkoli", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "30 g", "measure_nb": "30 g"}]'::jsonb, 'Boil the potatoes and carrots until tender. Fry the fish cakes until golden. Steam the broccoli briefly. Serve together with a knob of butter.', 'Kok poteter og gulrøtter møre. Stek fiskekakene gylne. Dampkok brokkolien kort. Server sammen med en klatt smør.', null),
  ('salmon-potatoes-vegetables', 'Salmon with Potatoes and Vegetables', 'Laks med poteter og grønnsaker', array['dinner'], 'Norwegian', false, '[{"canonical_name": "salmon", "name_en": "Salmon", "name_nb": "Laks", "measure_en": "600 g", "measure_nb": "600 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "broccoli", "name_en": "Broccoli", "name_nb": "Brokkoli", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "30 g", "measure_nb": "30 g"}, {"canonical_name": "lemon", "name_en": "Lemon", "name_nb": "Sitron", "measure_en": "1/2", "measure_nb": "1/2"}]'::jsonb, 'Boil the potatoes and carrots until tender. Pan-fry or oven-bake the salmon until just cooked through. Steam the broccoli. Serve with butter and a squeeze of lemon.', 'Kok poteter og gulrøtter møre. Stek eller ovnsbak laksen til den så vidt er gjennomstekt. Dampkok brokkolien. Server med smør og litt sitron.', null),
  ('salmon-rice-broccoli', 'Salmon with Rice and Broccoli', 'Laks med ris og brokkoli', array['dinner'], 'Norwegian', false, '[{"canonical_name": "salmon", "name_en": "Salmon", "name_nb": "Laks", "measure_en": "600 g", "measure_nb": "600 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "broccoli", "name_en": "Broccoli", "name_nb": "Brokkoli", "measure_en": "250 g", "measure_nb": "250 g"}, {"canonical_name": "soy sauce", "name_en": "Soy sauce", "name_nb": "Soyasaus", "measure_en": "2 tbsp", "measure_nb": "2 ss"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "20 g", "measure_nb": "20 g"}]'::jsonb, 'Cook the rice. Pan-fry the salmon in butter until just cooked through. Steam the broccoli. Serve together with a drizzle of soy sauce.', 'Kok risen. Stek laksen i smør til den så vidt er gjennomstekt. Dampkok brokkolien. Server sammen med litt soyasaus over.', null),
  ('oven-baked-salmon-vegetables', 'Oven-Baked Salmon with Vegetables', 'Ovnsbakt laks med grønnsaker', array['dinner'], 'Norwegian', false, '[{"canonical_name": "salmon", "name_en": "Salmon", "name_nb": "Laks", "measure_en": "600 g", "measure_nb": "600 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "olive oil", "name_en": "Olive oil", "name_nb": "Olivenolje", "measure_en": "2 tbsp", "measure_nb": "2 ss"}, {"canonical_name": "lemon", "name_en": "Lemon", "name_nb": "Sitron", "measure_en": "1/2", "measure_nb": "1/2"}]'::jsonb, 'Toss the diced potato, carrot, and pepper with olive oil and roast at 200°C (400°F) for 20 minutes. Add the salmon on top and bake a further 12-15 minutes. Finish with a squeeze of lemon.', 'Vend potet, gulrot og paprika i terninger med olivenolje og stek på 200°C i 20 minutter. Legg laksen oppå og stek videre i 12-15 minutter. Avslutt med litt sitron.', null),
  ('cod-potatoes-carrots', 'Cod with Potatoes and Carrots', 'Torsk med poteter og gulrøtter', array['dinner'], 'Norwegian', false, '[{"canonical_name": "cod", "name_en": "Cod", "name_nb": "Torsk", "measure_en": "600 g", "measure_nb": "600 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "40 g", "measure_nb": "40 g"}, {"canonical_name": "parsley", "name_en": "Parsley", "name_nb": "Persille", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Boil the potatoes and carrots until tender. Poach or pan-fry the cod until just cooked through. Serve with melted butter and chopped parsley.', 'Kok poteter og gulrøtter møre. Poacher eller stek torsken til den så vidt er gjennomstekt. Server med smeltet smør og hakket persille.', null),
  ('fish-gratin', 'Fish Gratin', 'Fiskegrateng', array['dinner'], 'Norwegian', false, '[{"canonical_name": "cod", "name_en": "Cod", "name_nb": "Torsk", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "5", "measure_nb": "5"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "100 g", "measure_nb": "100 g"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "20 g", "measure_nb": "20 g"}]'::jsonb, 'Layer sliced boiled potato and chunks of cod in a baking dish. Pour over the cream, top with cheese, and bake at 200°C (400°F) for 25-30 minutes.', 'Legg lag av skivet, kokt potet og biter av torsk i en ildfast form. Hell over fløten, topp med ost, og stek på 200°C i 25-30 minutter.', null),
  ('fish-soup', 'Fish Soup', 'Fiskesuppe', array['dinner'], 'Norwegian', false, '[{"canonical_name": "cod", "name_en": "Cod", "name_nb": "Torsk", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "2 dl", "measure_nb": "2 dl"}, {"canonical_name": "vegetable stock", "name_en": "Vegetable stock", "name_nb": "Grønnsakskraft", "measure_en": "6 dl", "measure_nb": "6 dl"}, {"canonical_name": "dill", "name_en": "Dill", "name_nb": "Dill", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Simmer the diced carrot and potato in the stock until tender. Add the cream and cubed cod, and simmer gently for 5-8 minutes until the fish is cooked. Finish with fresh dill.', 'La gulrot og potet i terninger småkoke i kraften til de er møre. Tilsett fløte og torsk i biter, og la det trekke forsiktig i 5-8 minutter til fisken er gjennomstekt. Avslutt med frisk dill.', null),
  ('meatballs-brown-gravy-potatoes', 'Norwegian Meatballs with Brown Gravy and Potatoes', 'Kjøttkaker med brun saus og poteter', array['dinner'], 'Norwegian', false, '[{"canonical_name": "meatballs", "name_en": "Meatballs", "name_nb": "Kjøttkaker", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "800 g", "measure_nb": "800 g"}, {"canonical_name": "brown gravy", "name_en": "Brown gravy", "name_nb": "Brun saus", "measure_en": "4 dl", "measure_nb": "4 dl"}, {"canonical_name": "peas", "name_en": "Peas", "name_nb": "Erter", "measure_en": "150 g", "measure_nb": "150 g"}]'::jsonb, 'Boil the potatoes until tender. Heat the meatballs in the brown gravy until warmed through. Boil the peas briefly and serve everything together.', 'Kok potetene møre. Varm kjøttkakene i den brune sausen til de er gjennomvarme. Kok ertene kort og server alt sammen.', null),
  ('beef-patties-potatoes-onions', 'Beef Patties with Potatoes and Onions', 'Karbonader med poteter og løk', array['dinner'], 'Norwegian', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "800 g", "measure_nb": "800 g"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "breadcrumbs", "name_en": "Breadcrumbs", "name_nb": "Brødsmuler", "measure_en": "1/2 dl", "measure_nb": "1/2 dl"}]'::jsonb, 'Mix the ground beef with egg and breadcrumbs, shape into patties, and fry until cooked through. Fry the sliced onion until golden. Boil the potatoes and serve together.', 'Bland kjøttdeigen med egg og brødsmuler, form til karbonader, og stek gjennomstekt. Stek løken i skiver gyllen. Kok potetene og server sammen.', null),
  ('chicken-breast-rice-vegetables', 'Chicken Breast with Rice and Vegetables', 'Kyllingfilet med ris og grønnsaker', array['dinner'], 'Everyday', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "broccoli", "name_en": "Broccoli", "name_nb": "Brokkoli", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "olive oil", "name_en": "Olive oil", "name_nb": "Olivenolje", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Cook the rice. Pan-fry the chicken breast until cooked through and slice. Steam the broccoli and carrot. Serve together with a drizzle of olive oil.', 'Kok risen. Stek kyllingfileten gjennomstekt og skjær i skiver. Dampkok brokkoli og gulrot. Server sammen med litt olivenolje over.', null),
  ('oven-baked-chicken-potatoes', 'Oven-Baked Chicken with Potatoes', 'Ovnsbakt kylling med poteter', array['dinner'], 'Everyday', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "600 g", "measure_nb": "600 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "2 cloves", "measure_nb": "2 fedd"}, {"canonical_name": "olive oil", "name_en": "Olive oil", "name_nb": "Olivenolje", "measure_en": "2 tbsp", "measure_nb": "2 ss"}, {"canonical_name": "paprika powder", "name_en": "Paprika powder", "name_nb": "Paprikapulver", "measure_en": "1 tsp", "measure_nb": "1 ts"}]'::jsonb, 'Toss the quartered potatoes and chicken with olive oil, garlic, and paprika powder. Roast at 200°C (400°F) for 35-40 minutes until the chicken is cooked through.', 'Vend poteter i båter og kylling med olivenolje, hvitløk og paprikapulver. Stek på 200°C i 35-40 minutter til kyllingen er gjennomstekt.', null),
  ('chicken-casserole-vegetables', 'Chicken Casserole with Vegetables', 'Kyllinggryte med grønnsaker', array['dinner'], 'Everyday', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "1 can", "measure_nb": "1 boks"}, {"canonical_name": "chicken stock", "name_en": "Chicken stock", "name_nb": "Kyllingkraft", "measure_en": "2 dl", "measure_nb": "2 dl"}]'::jsonb, 'Brown the diced chicken with the onion. Add the carrot, pepper, canned tomatoes, and stock, and simmer for 20 minutes until the vegetables are tender.', 'Brun kylling i terninger sammen med løk. Tilsett gulrot, paprika, hermetiske tomater og kraft, og la det småkoke i 20 minutter til grønnsakene er møre.', null),
  ('chicken-creamy-sauce', 'Chicken in Creamy Sauce', 'Kylling i fløtesaus', array['dinner'], 'Everyday', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "mushroom", "name_en": "Mushroom", "name_nb": "Sopp", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "1 clove", "measure_nb": "1 fedd"}, {"canonical_name": "chicken stock", "name_en": "Chicken stock", "name_nb": "Kyllingkraft", "measure_en": "1 dl", "measure_nb": "1 dl"}]'::jsonb, 'Fry the sliced chicken and mushroom with the garlic. Add the cream and stock and simmer for 10 minutes until thickened slightly. Serve with rice or potatoes.', 'Stek kylling og sopp i skiver sammen med hvitløk. Tilsett fløte og kraft og la det småkoke i 10 minutter til sausen tykner litt. Server med ris eller poteter.', null),
  ('chicken-burger', 'Chicken Burger', 'Kyllingburger', array['dinner'], 'Burgers', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "hamburger bun", "name_en": "Hamburger bun", "name_nb": "Hamburgerbrød", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/4 head", "measure_nb": "1/4 hode"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "mayonnaise", "name_en": "Mayonnaise", "name_nb": "Majones", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Pound the chicken breast flat and fry until cooked through. Toast the buns and assemble with lettuce, tomato, chicken, and mayonnaise.', 'Bank kyllingfileten flat og stek gjennomstekt. Rist boller og sett sammen med salat, tomat, kylling og majones.', null),
  ('homemade-hamburger', 'Homemade Hamburger', 'Hjemmelaget hamburger', array['dinner'], 'Burgers', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "hamburger bun", "name_en": "Hamburger bun", "name_nb": "Hamburgerbrød", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "4 slices", "measure_nb": "4 skiver"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/4 head", "measure_nb": "1/4 hode"}, {"canonical_name": "ketchup", "name_en": "Ketchup", "name_nb": "Ketchup", "measure_en": "to taste", "measure_nb": "etter smak"}]'::jsonb, 'Shape the ground beef into patties, season, and fry to your liking. Toast the buns and assemble with cheese, lettuce, patty, and ketchup.', 'Form kjøttdeigen til karbonader, krydre og stek etter smak. Rist boller og sett sammen med ost, salat, karbonade og ketchup.', null),
  ('pita-beef-mince-salad', 'Pita with Beef Mince and Salad', 'Pita med kjøttdeig og salat', array['lunch','dinner'], 'Mediterranean', false, '[{"canonical_name": "pita bread", "name_en": "Pita bread", "name_nb": "Pitabrød", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/4 head", "measure_nb": "1/4 hode"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "cumin", "name_en": "Cumin", "name_nb": "Spisskummen", "measure_en": "1 tsp", "measure_nb": "1 ts"}]'::jsonb, 'Brown the ground beef with the cumin. Warm the pita bread and fill with beef, lettuce, and diced tomato.', 'Brun kjøttdeigen med spisskummen. Varm pitabrødet og fyll med kjøttdeig, salat og tomat i terninger.', null),
  ('pita-chicken', 'Pita with Chicken', 'Pita med kylling', array['lunch','dinner'], 'Mediterranean', false, '[{"canonical_name": "pita bread", "name_en": "Pita bread", "name_nb": "Pitabrød", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "lettuce", "name_en": "Lettuce", "name_nb": "Issalat", "measure_en": "1/4 head", "measure_nb": "1/4 hode"}, {"canonical_name": "cucumber", "name_en": "Cucumber", "name_nb": "Agurk", "measure_en": "1/2", "measure_nb": "1/2"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "1 clove", "measure_nb": "1 fedd"}]'::jsonb, 'Fry the sliced chicken with the garlic until cooked through. Warm the pita bread and fill with chicken, lettuce, and cucumber.', 'Stek kyllingstrimlene sammen med hvitløk til de er gjennomstekte. Varm pitabrødet og fyll med kylling, salat og agurk.', null),
  ('pytt-i-panne', 'Pytt i Panne', 'Pytt i panne', array['dinner'], 'Norwegian', false, '[{"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "sausages", "name_en": "Sausages", "name_nb": "Pølser", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "30 g", "measure_nb": "30 g"}]'::jsonb, 'Dice and fry the potatoes in butter until golden. Add diced onion, sausages, and cooked meat and fry until hot through. Serve with a fried egg on top.', 'Terning og stek potetene i smør til de er gylne. Ha i løk, pølser og kjøtt i terninger og stek til alt er gjennomvarmt. Server med speilegg på toppen.', null),
  ('lapskaus', 'Lapskaus', 'Lapskaus', array['dinner'], 'Norwegian', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "beef stock", "name_en": "Beef stock", "name_nb": "Oksekraft", "measure_en": "6 dl", "measure_nb": "6 dl"}]'::jsonb, 'Brown the beef with the onion, then add the diced potato and carrot and the stock. Simmer for 25-30 minutes until the vegetables are tender.', 'Brun kjøttet sammen med løk, tilsett potet og gulrot i terninger og kraften. La det småkoke i 25-30 minutter til grønnsakene er møre.', null),
  ('tomato-soup-egg', 'Tomato Soup with Egg', 'Tomatsuppe med egg', array['lunch','dinner'], 'Soups', true, '[{"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "2 cans", "measure_nb": "2 bokser"}, {"canonical_name": "vegetable stock", "name_en": "Vegetable stock", "name_nb": "Grønnsakskraft", "measure_en": "5 dl", "measure_nb": "5 dl"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "4", "measure_nb": "4"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "1 dl", "measure_nb": "1 dl"}]'::jsonb, 'Sauté the onion, add the canned tomatoes and stock, and simmer 15 minutes. Blend smooth and stir in the cream. Poach or boil the eggs and add one to each bowl.', 'Fres løken, tilsett hermetiske tomater og kraft, og la det småkoke i 15 minutter. Kjør glatt og rør inn fløten. Poacher eller kok eggene og legg ett i hver tallerken.', null),
  ('creamy-cauliflower-soup', 'Creamy Cauliflower Soup', 'Kremet blomkålsuppe', array['lunch','dinner'], 'Soups', true, '[{"canonical_name": "cauliflower", "name_en": "Cauliflower", "name_nb": "Blomkål", "measure_en": "1 head", "measure_nb": "1 hode"}, {"canonical_name": "vegetable stock", "name_en": "Vegetable stock", "name_nb": "Grønnsakskraft", "measure_en": "6 dl", "measure_nb": "6 dl"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "1 dl", "measure_nb": "1 dl"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "20 g", "measure_nb": "20 g"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "1 clove", "measure_nb": "1 fedd"}]'::jsonb, 'Simmer the cauliflower florets with garlic in the stock until soft, about 15 minutes. Blend smooth and stir in the cream and butter.', 'La blomkålbukettene småkoke med hvitløk i kraften til de er møre, ca. 15 minutter. Kjør glatt og rør inn fløte og smør.', null),
