  ('pancakes-bacon', 'Pancakes with Bacon', 'Pannekaker med bacon', array['breakfast','dinner'], 'Nordic', false, '[{"canonical_name": "flour", "name_en": "Flour", "name_nb": "Mel", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "milk", "name_en": "Milk", "name_nb": "Melk", "measure_en": "5 dl", "measure_nb": "5 dl"}, {"canonical_name": "eggs", "name_en": "Eggs", "name_nb": "Egg", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "bacon", "name_en": "Bacon", "name_nb": "Bacon", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "butter", "name_en": "Butter", "name_nb": "Smør", "measure_en": "1 tbsp", "measure_nb": "1 ss"}]'::jsonb, 'Whisk the flour, milk, and eggs into a smooth batter. Fry thin pancakes in butter. Fry the bacon separately until crisp and serve alongside.', 'Visp mel, melk og egg til en jevn røre. Stek tynne pannekaker i smør. Stek baconet sprøtt for seg og server ved siden av.', null),
  ('nachos-beef-mince', 'Nachos with Beef Mince', 'Nachos med kjøttdeig', array['dinner'], 'Mexican', false, '[{"canonical_name": "nacho chips", "name_en": "Nacho chips", "name_nb": "Nachos", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "tomato", "name_en": "Tomato", "name_nb": "Tomat", "measure_en": "2", "measure_nb": "2"}, {"canonical_name": "taco seasoning", "name_en": "Taco seasoning", "name_nb": "Tacokrydder", "measure_en": "1 packet", "measure_nb": "1 pose"}]'::jsonb, 'Brown the ground beef with the taco seasoning. Spread the nacho chips on an oven tray, top with beef and cheese, and bake at 200°C (400°F) until the cheese melts. Finish with diced tomato.', 'Brun kjøttdeigen med tacokrydder. Fordel nachos på et ovnsbrett, topp med kjøttdeig og ost, og stek på 200°C til osten har smeltet. Avslutt med tomat i terninger.', null),
  ('ham-cheese-pizza', 'Ham and Cheese Pizza', 'Pizza med skinke og ost', array['dinner'], 'Pizza', false, '[{"canonical_name": "pizza dough", "name_en": "Pizza dough", "name_nb": "Pizzadeig", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "tomato paste", "name_en": "Tomato paste", "name_nb": "Tomatpuré", "measure_en": "3 tbsp", "measure_nb": "3 ss"}, {"canonical_name": "ham", "name_en": "Ham", "name_nb": "Skinke", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "200 g", "measure_nb": "200 g"}]'::jsonb, 'Spread the tomato paste over the pizza dough and top with ham and cheese. Bake at 220°C (425°F) for 12-15 minutes until golden.', 'Smør tomatpuré på pizzadeigen og topp med skinke og ost. Stek på 220°C i 12-15 minutter til pizzaen er gyllen.', null),
  ('beef-mince-pizza', 'Beef Mince Pizza', 'Pizza med kjøttdeig', array['dinner'], 'Pizza', false, '[{"canonical_name": "pizza dough", "name_en": "Pizza dough", "name_nb": "Pizzadeig", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "tomato paste", "name_en": "Tomato paste", "name_nb": "Tomatpuré", "measure_en": "3 tbsp", "measure_nb": "3 ss"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "300 g", "measure_nb": "300 g"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "200 g", "measure_nb": "200 g"}]'::jsonb, 'Brown the ground beef with the onion. Spread tomato paste over the dough, top with the beef mixture and cheese, and bake at 220°C (425°F) for 12-15 minutes.', 'Brun kjøttdeigen sammen med løk. Smør tomatpuré på deigen, topp med kjøttdeigblandingen og ost, og stek på 220°C i 12-15 minutter.', null),
  ('chicken-oven-roasted-vegetables', 'Chicken with Oven-Roasted Vegetables', 'Kylling med ovnsbakte grønnsaker', array['dinner'], 'Everyday', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "5", "measure_nb": "5"}, {"canonical_name": "carrot", "name_en": "Carrot", "name_nb": "Gulrot", "measure_en": "3", "measure_nb": "3"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "olive oil", "name_en": "Olive oil", "name_nb": "Olivenolje", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Toss the chopped vegetables with olive oil and roast at 200°C (400°F) for 15 minutes. Add the chicken on top and roast a further 20-25 minutes until cooked through.', 'Vend de oppkuttede grønnsakene med olivenolje og stek på 200°C i 15 minutter. Legg kyllingen oppå og stek videre 20-25 minutter til den er gjennomstekt.', null),
  ('beef-mince-potato-casserole', 'Beef Mince and Potato Casserole', 'Kjøttdeig- og potetgrateng', array['dinner'], 'Norwegian', false, '[{"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "500 g", "measure_nb": "500 g"}, {"canonical_name": "potato", "name_en": "Potato", "name_nb": "Potet", "measure_en": "6", "measure_nb": "6"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "100 g", "measure_nb": "100 g"}]'::jsonb, 'Brown the ground beef with the onion. Layer with sliced potato in a baking dish, pour over the cream, top with cheese, and bake at 200°C (400°F) for 35-40 minutes.', 'Brun kjøttdeigen sammen med løk. Legg lagvis med skivet potet i en ildfast form, hell over fløten, topp med ost, og stek på 200°C i 35-40 minutter.', null),
  ('salmon-pasta', 'Salmon Pasta', 'Lakspasta', array['dinner'], 'Pasta', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "salmon", "name_en": "Salmon", "name_nb": "Laks", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "dill", "name_en": "Dill", "name_nb": "Dill", "measure_en": "to taste", "measure_nb": "etter smak"}, {"canonical_name": "lemon", "name_en": "Lemon", "name_nb": "Sitron", "measure_en": "1/2", "measure_nb": "1/2"}]'::jsonb, 'Cook the pasta. Cube the salmon and simmer gently in the cream for 5-6 minutes until just cooked. Toss with the pasta, dill, and a squeeze of lemon.', 'Kok pastaen. Del laksen i biter og la den trekke forsiktig i fløten i 5-6 minutter til den så vidt er gjennomstekt. Vend sammen med pasta, dill og litt sitron.', null),
  ('creamy-bacon-pasta', 'Creamy Bacon Pasta', 'Kremet baconpasta', array['dinner'], 'Pasta', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "bacon", "name_en": "Bacon", "name_nb": "Bacon", "measure_en": "200 g", "measure_nb": "200 g"}, {"canonical_name": "cream", "name_en": "Cream", "name_nb": "Fløte", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "cheese", "name_en": "Cheese", "name_nb": "Ost", "measure_en": "50 g", "measure_nb": "50 g"}]'::jsonb, 'Fry the bacon and onion until golden. Add the cream and simmer a few minutes, then stir in the cheese. Toss with the cooked pasta.', 'Stek bacon og løk gyllent. Tilsett fløte og la det småkoke noen minutter, rør inn osten. Vend sammen med kokt pasta.', null),
  ('one-pot-beef-mince-pasta', 'One-Pot Beef Mince Pasta', 'Enkel kjøttdeigpasta i én gryte', array['dinner'], 'Pasta', false, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "350 g", "measure_nb": "350 g"}, {"canonical_name": "ground beef", "name_en": "Ground beef", "name_nb": "Kjøttdeig", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "1 can", "measure_nb": "1 boks"}, {"canonical_name": "beef stock", "name_en": "Beef stock", "name_nb": "Oksekraft", "measure_en": "4 dl", "measure_nb": "4 dl"}, {"canonical_name": "onion", "name_en": "Onion", "name_nb": "Løk", "measure_en": "1", "measure_nb": "1"}]'::jsonb, 'Brown the ground beef with the onion in a large pot. Add the pasta, canned tomatoes, and stock, and simmer, stirring occasionally, until the pasta is tender and most of the liquid is absorbed.', 'Brun kjøttdeigen sammen med løk i en stor gryte. Tilsett pasta, hermetiske tomater og kraft, og la det småkoke, rør innimellom, til pastaen er mør og det meste av væsken er tatt opp.', null),
  ('vegetarian-tomato-vegetable-pasta', 'Vegetarian Tomato and Vegetable Pasta', 'Vegetarpasta med tomat og grønnsaker', array['dinner'], 'Pasta', true, '[{"canonical_name": "pasta", "name_en": "Pasta", "name_nb": "Pasta", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "canned tomatoes", "name_en": "Canned tomatoes", "name_nb": "Hermetiske tomater", "measure_en": "2 cans", "measure_nb": "2 bokser"}, {"canonical_name": "bell pepper", "name_en": "Bell pepper", "name_nb": "Paprika", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "mushroom", "name_en": "Mushroom", "name_nb": "Sopp", "measure_en": "150 g", "measure_nb": "150 g"}, {"canonical_name": "garlic", "name_en": "Garlic", "name_nb": "Hvitløk", "measure_en": "2 cloves", "measure_nb": "2 fedd"}]'::jsonb, 'Sauté the pepper, mushroom, and garlic, add the canned tomatoes, and simmer 15 minutes. Toss with the cooked pasta.', 'Fres paprika, sopp og hvitløk, tilsett hermetiske tomater, og la det småkoke i 15 minutter. Vend sammen med kokt pasta.', null),
  ('salmon-poke-bowl', 'Salmon Poke Bowl', 'Lakse-pokebowl', array['lunch','dinner'], 'Asian', false, '[{"canonical_name": "salmon", "name_en": "Salmon", "name_nb": "Laks", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "cucumber", "name_en": "Cucumber", "name_nb": "Agurk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "avocado", "name_en": "Avocado", "name_nb": "Avokado", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "soy sauce", "name_en": "Soy sauce", "name_nb": "Soyasaus", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Cook the rice and let it cool slightly. Cube the raw or lightly seared salmon and marinate briefly in soy sauce. Assemble bowls with rice, salmon, cucumber, and avocado.', 'Kok risen og la den avkjøles litt. Del rå eller lett stekt laks i terninger og la den marinere litt i soyasaus. Sett sammen boller med ris, laks, agurk og avokado.', null),
  ('chicken-poke-bowl', 'Chicken Poke Bowl', 'Kylling-pokebowl', array['lunch','dinner'], 'Asian', false, '[{"canonical_name": "chicken breast", "name_en": "Chicken breast", "name_nb": "Kyllingfilet", "measure_en": "400 g", "measure_nb": "400 g"}, {"canonical_name": "rice", "name_en": "Rice", "name_nb": "Ris", "measure_en": "3 dl", "measure_nb": "3 dl"}, {"canonical_name": "cucumber", "name_en": "Cucumber", "name_nb": "Agurk", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "avocado", "name_en": "Avocado", "name_nb": "Avokado", "measure_en": "1", "measure_nb": "1"}, {"canonical_name": "soy sauce", "name_en": "Soy sauce", "name_nb": "Soyasaus", "measure_en": "2 tbsp", "measure_nb": "2 ss"}]'::jsonb, 'Cook the rice and let it cool slightly. Fry and dice the chicken. Assemble bowls with rice, chicken, cucumber, and avocado, and drizzle with soy sauce.', 'Kok risen og la den avkjøles litt. Stek og terning kyllingen. Sett sammen boller med ris, kylling, agurk og avokado, og ha over litt soyasaus.', null)
